import { DAILY_REWARDS } from "./save.js";
import { icon } from "./icons.js";
import { COURSES, getHole, relative } from "./courses.js";
import { coins, button, minutes } from "./views.js";
export function holeDialog(result, reward) {
  return `<div class="result"><div class="result-icon">${icon(result.strokes <= result.par ? "trophy" : "flag")}</div><div class="eyebrow centered">HOLE ${result.index + 1} COMPLETE</div><h2>${result.label}</h2><p>${result.strokes <= result.par ? "A little shot worth remembering." : "A fresh green is just around the corner."}</p><div class="result-score"><div><strong>${result.strokes}</strong><span>Strokes</span></div><div><strong>${result.par}</strong><span>Par</span></div><div><strong>${relative(result.strokes - result.par)}</strong><span>Score</span></div></div><div class="reward-line">${result.round.practice ? "Practice round · No rewards" : `${coins(reward.coins)}<span>+${reward.xp} XP</span>`}</div><div class="modal-actions">${button((result.index === (result.round.holeCount || 9) - 1 ? "View scorecard" : "Next hole") + icon("arrow"), "next-hole", "", "button wide yellow")}</div></div>`;
}
export function courseDialog(round, reward) {
  const pars = round.strokes.map((_, i) => getHole(round.courseIndex, i).par),
    total = round.strokes.reduce((a, b) => a + b, 0),
    par = pars.reduce((a, b) => a + b, 0);
  return `<div class="result"><div class="eyebrow centered">THAT'S A ROUND</div><h2>${COURSES[round.courseIndex].name}</h2><p>Nine holes. A little adventure of your own.</p><div class="result-score"><div><strong>${total}</strong><span>Total strokes</span></div><div><strong>${relative(total - par)}</strong><span>To par</span></div><div><strong>${minutes(round.time)}</strong><span>Round time</span></div></div><div class="table-scroll"><table class="scorecard"><thead><tr><th>Hole</th>${pars.map((_, i) => `<th>${i + 1}</th>`).join("")}<th>Total</th></tr></thead><tbody><tr><th>Par</th>${pars.map((n) => `<td>${n}</td>`).join("")}<td>${par}</td></tr><tr><th>Strokes</th>${round.strokes.map((n, i) => `<td class="${n < pars[i] ? "under-par" : ""}">${n}</td>`).join("")}<td>${total}</td></tr><tr><th>Score</th>${round.strokes.map((n, i) => `<td>${relative(n - pars[i])}</td>`).join("")}<td>${relative(total - par)}</td></tr></tbody></table></div><div class="reward-line">${round.practice ? "Practice round · Results are not recorded" : `${coins(reward.coins)}<span>+${reward.xp} XP completion bonus</span>`}</div><div class="modal-actions">${button("Back to clubhouse", "round-exit", "", "button secondary")}${button("Another round " + icon("play"), "replay", "", "button yellow")}</div></div>`;
}
export function dailyDialog(progress) {
  const s = progress.loginStatus();
  return `<div class="result"><div class="result-icon">${icon("gift")}</div><h2>A little something for you.</h2><p>Drop by each day to grow your streak.<br>Day seven brings the exclusive Sunday Special ball.</p><div class="login-grid">${Array.from({ length: 7 }, (_, i) => `<div class="login-day ${i + 1 === s.day ? "today" : ""} ${i + 1 < s.day ? "claimed" : ""}"><span>DAY ${i + 1}</span>${icon(i === 6 ? "ball" : i + 1 < s.day ? "check" : "gift")}<strong>${DAILY_REWARDS[i] + (i === 6 ? " + ball" : " coins")}</strong></div>`).join("")}</div>${button(s.claimed ? "All yours. See you tomorrow!" : `Claim day ${s.day} reward`, "claim-login", s.claimed ? "disabled" : "", "button yellow wide")}<p class="small-note">A new day begins at 00:00 UTC. Missing a day starts a fresh streak.</p></div>`;
}
export function settingsDialog(s) {
  const choices=(key,label,options)=>`<fieldset class="settings-choice"><legend>${label}</legend><div class="setting-segments">${options.map(([value,name,detail])=>`<label class="setting-option"><input type="radio" name="setting-${key}" data-setting="${key}" value="${value}" ${s[key]===value?'checked':''}><span>${key==='theme'?'<i class="appearance-swatch '+value+'" aria-hidden="true"></i>':''}<strong>${name}</strong>${detail?'<small>'+detail+'</small>':''}<b class="choice-check" aria-hidden="true">✓</b></span></label>`).join('')}</div></fieldset>`;
  const range=(id,label,min,max,step)=>`<label class="setting-row setting-slider" for="setting-${id}"><span>${label}</span><input id="setting-${id}" data-setting="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${s[id]}"><output>${max===1?Math.round(s[id]*100)+'%':s[id]+'×'}</output></label>`;
  return `<div class="settings-heading"><span class="menu-kicker">MAKE IT YOURS</span><h2>Settings</h2><p>Your game, at your own pace.</p></div><div class="settings-list settings-custom">${choices('theme','Appearance',[['dark','Dark'],['light','Light']])}${choices('courseWeather','Time & weather',[['normal','Daytime','Sunny'],['night','Night','Moonlit'],['rainy','Rain','Overcast']])}${choices('graphics','Graphics quality',[['auto','Auto','Fits this device'],['low','Low','Less battery'],['medium','Medium','Balanced'],['high','High','More detail']])}<section class="settings-group" aria-labelledby="settings-sound"><h3 id="settings-sound">Sound</h3>${choices('musicStyle','Music choice',[['majestic','Majestic','Wide & soaring'],['upbeat','Upbeat','Bright & bouncy'],['calm','Calm','Soft & peaceful']])}${range('master','Master volume',0,1,.01)}${range('music','Music',0,1,.01)}${range('sfx','Sound effects',0,1,.01)}</section><section class="settings-group" aria-labelledby="settings-camera"><h3 id="settings-camera">Camera</h3>${range('cameraSensitivity','Camera sensitivity',.3,2,.1)}${range('zoomSensitivity','Zoom sensitivity',.3,2,.1)}</section><section class="settings-group" aria-labelledby="settings-course"><h3 id="settings-course">On the course</h3><label class="setting-row" for="setting-shotGuide"><span>Shot path</span><select id="setting-shotGuide" aria-label="Shot path" data-setting="shotGuide"><option value="full" ${s.shotGuide!=='directional'?'selected':''}>Full path</option><option value="directional" ${s.shotGuide==='directional'?'selected':''}>Direction only</option></select></label>${[['shadows','Soft shadows'],['particles','Particles & celebrations'],['aimGuide','Aiming guide'],['showOpponents','Show opponents, trails & emotes']].map(([id,label])=>`<label class="setting-row" for="setting-${id}"><span>${label}</span><input class="toggle" role="switch" id="setting-${id}" type="checkbox" data-setting="${id}" ${s[id]?'checked':''}></label>`).join('')}</section></div><div class="modal-actions">${button('Credits','credits','','button secondary')}${button(icon('fullscreen')+'Fullscreen','fullscreen','','button secondary')}${button('All set','close-modal','','button yellow')}</div><nav class="settings-legal" aria-label="Legal and support"><a href="/privacy.html" target="_blank" rel="noopener">Privacy policy</a><a href="/terms.html" target="_blank" rel="noopener">Terms of service</a><a href="/cookies.html" target="_blank" rel="noopener">Cookies</a><a href="/community-rules.html" target="_blank" rel="noopener">Community rules</a><a href="/copyright.html" target="_blank" rel="noopener">Copyright</a><a href="/contact.html" target="_blank" rel="noopener">Contact &amp; support</a></nav>`;
}
export function helpDialog() {
  return `<h2>A little swing goes a long way.</h2><p>Move the pointer across the green to aim. Hold the left mouse button to build power, then release to putt.</p><div class="help-grid"><div><kbd>Right drag</kbd><span>Orbit the camera</span></div><div><kbd>Scroll</kbd><span>Zoom in or out</span></div><div><kbd>← →</kbd><span>Fine-tune your aim</span></div><div><kbd>↑ ↓</kbd><span>Adjust shot power</span></div><div><kbd>Enter</kbd><span>Hit at selected power</span></div><div><kbd>Space</kbd><span>Hold to charge, release to hit</span></div><div><kbd>Q / E</kbd><span>Rotate camera</span></div><div><kbd>R</kbd><span>Previous shot + 1 penalty</span></div><div><kbd>Esc</kbd><span>Pause the round</span></div></div><h3>Read the green</h3><div class="surface-guide"><span><i style="background:#99c568"></i>Grass · steady roll</span><span><i style="background:#e5cd93"></i>Sand · slows you down</span><span><i style="background:#acdfe8"></i>Ice · keep on gliding</span><span><i style="background:#8b7558"></i>Mud · heavy friction</span><span><i style="background:#ead175"></i>Gold · speed boost</span><span><i style="background:#de9b87"></i>Coral · jump pad</span><span><i style="background:#64bdd1"></i>Water · reset + 1 stroke</span></div><p class="small-note">Cross water on the wooden bridge. Aim through the moving gate. Look for narrow timber shortcuts and floating gold coins.</p>${button("Got it. Let’s putt.", "close-modal", "", "button yellow wide")}`;
}
